/**
 * OWNER: gameplay engineer.
 * Authored in-run backdrop art (public/assets/backdrop/*.svg, generated by tools/backdrop-art): texture keys, native
 * sizes and the loader queue. Same rules as the menu art (ui/MenuArt.js):
 *  1. Accent colour is never baked. The art is white/greyscale and is tinted from the live palette, so colour-blind mode
 *     and each biome's tint recolour it.
 *  2. Art is optional. A file that 404s or fails to decode never becomes a texture, and BiomeFx falls back to the
 *     procedural Background drawing, so a missing asset can never block a run.
 *
 * Each SVG is rasterised once, 1:1 at its native size (`load.svg(key, url, {width, height})`), and `pixelArt: true`
 * keeps it crisp; every placement is on whole pixels.
 */

/** Relative (no leading slash) so the game also works under a sub-path; Vite serves public/ at the site root. */
export const BACKDROP_ART_BASE = 'assets/backdrop/';

/** @type {Readonly<Object<string, Readonly<{key:string, file:string, w:number, h:number}>>>} */
export const BACKDROP_ART = Object.freeze({
  debutmontSky: Object.freeze({ key: 'bd-debutmont-sky', file: 'debutmont-sky.svg', w: 480, h: 160 }),
  debutmontRidgeFar: Object.freeze({ key: 'bd-debutmont-ridge-far', file: 'debutmont-ridge-far.svg', w: 960, h: 208 }),
  debutmontRidgeNear: Object.freeze({ key: 'bd-debutmont-ridge-near', file: 'debutmont-ridge-near.svg', w: 960, h: 160 }),
  arcadeSky: Object.freeze({ key: 'bd-arcade-sky', file: 'arcade-sky.svg', w: 480, h: 120 }),
  arcadeSun: Object.freeze({ key: 'bd-arcade-sun', file: 'arcade-sun.svg', w: 112, h: 60 }),
  arcadeSkyline: Object.freeze({ key: 'bd-arcade-skyline', file: 'arcade-skyline.svg', w: 480, h: 48 }),
});

/**
 * Queue every backdrop SVG on a loader (call from a scene's preload()). Tolerates loaders without svg support
 * (headless/Jest stubs) by queuing nothing.
 * @param {Phaser.Loader.LoaderPlugin|any} load
 * @returns {number} files queued
 */
export function queueBackdropArt(load) {
  if (!load || typeof load.svg !== 'function') return 0;
  let n = 0;
  for (const a of Object.values(BACKDROP_ART)) {
    if (load.textureManager && typeof load.textureManager.exists === 'function' && load.textureManager.exists(a.key)) continue;
    load.svg(a.key, BACKDROP_ART_BASE + a.file, { width: a.w, height: a.h });
    n++;
  }
  return n;
}

/**
 * Did this texture load? False for unknown names, Phaser's placeholder textures and scenes without a texture manager.
 * @param {Phaser.Scene} scene @param {string} name BACKDROP_ART name @returns {boolean}
 */
export function hasBackdropArt(scene, name) {
  const a = BACKDROP_ART[name];
  const tm = scene && scene.textures;
  if (!a || !tm || typeof tm.exists !== 'function') return false;
  try {
    return tm.exists(a.key) === true;
  } catch (e) {
    return false;
  }
}
